function draw(ctx, t, p) {
  const W = 960, H = 540;
  const TAU = Math.PI * 2;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const lerp = (a, b, u) => a + (b - a) * u;
  const num = (v, d) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
  const fmt = (v, n) => Number.isFinite(v) ? v.toFixed(n === undefined ? 2 : n) : "—";

  // ---------- 交互参数 ----------
  const x0raw = clamp(num(p.x0, 1), -2, 2);
  const mag = clamp(num(p.h, 0.5), 0.02, 2);
  const side = num(p.side, 1) < 0 ? -1 : 1;
  const example = num(p.example, 0) >= 0.5 ? 1 : 0;

  // ---------- 78 秒 / 6 镜累计时间轴 ----------
  const sceneEnds = [8, 22, 36, 50, 64, 78];
  const TOTAL = 78;
  const sec = clamp(t, 0, 1) * TOTAL;
  let si = 0;
  while (si < 5 && sec >= sceneEnds[si]) si++;
  const t0 = si === 0 ? 0 : sceneEnds[si - 1];
  const local = clamp((sec - t0) / (sceneEnds[si] - t0), 0, 1);

  // S6 固定为 |x| 反例；示例开关选 |x| 时也把反例锁在 x0 = 0
  const isAbs = (si === 5) || (example === 1);
  const x0 = isAbs ? 0 : x0raw;

  // S3 由时间轴把步长从 |h| 连续缩到 0.02，且始终从右侧；其余镜头由滑杆控制
  let h;
  if (si === 2) h = lerp(mag, 0.02, local);
  else h = side * mag;

  const f = x => isAbs ? Math.abs(x) : x * x;
  const deriv = isAbs ? (x0 < 0 ? -1 : x0 > 0 ? 1 : NaN) : 2 * x0;
  const qx = x0 + h;
  const fp = f(x0);
  const fq = f(qx);
  const slope = Math.abs(h) > 1e-12 ? (fq - fp) / h : NaN;
  const residual = isAbs ? NaN : (fq - (fp + deriv * h));

  // ---------- 画布底色与标题 ----------
  ctx.fillStyle = "#f7fafc";
  ctx.fillRect(0, 0, W, H);
  ctx.fillStyle = "#18324a";
  ctx.font = "bold 23px sans-serif";
  ctx.fillText("割线旋转成切线：导数的极限定义", 35, 42);
  ctx.font = "17px sans-serif";
  ctx.fillStyle = "#5a7286";
  ctx.fillText("h ≠ 0；总时长 78 秒", 726, 42);

  // ---------- 坐标系 ----------
  const GX0 = 45, GX1 = 620, GY0 = 95, GY1 = 415;
  const xmin = -4.6, xmax = 4.6, ymin = -1.2, ymax = 17.0;
  const X = x => GX0 + (x - xmin) / (xmax - xmin) * (GX1 - GX0);
  const Y = y => GY1 - (y - ymin) / (ymax - ymin) * (GY1 - GY0);

  ctx.fillStyle = "#ffffff";
  ctx.fillRect(GX0, GY0, GX1 - GX0, GY1 - GY0);
  ctx.strokeStyle = "#cfe0ea";
  ctx.lineWidth = 1;
  ctx.strokeRect(GX0 + 0.5, GY0 + 0.5, GX1 - GX0 - 1, GY1 - GY0 - 1);

  ctx.strokeStyle = "#e6f0f7";
  ctx.lineWidth = 1;
  for (let gx = -4; gx <= 4; gx++) {
    ctx.beginPath(); ctx.moveTo(X(gx), GY0); ctx.lineTo(X(gx), GY1); ctx.stroke();
  }
  for (let gy = 0; gy <= 16; gy += 2) {
    ctx.beginPath(); ctx.moveTo(GX0, Y(gy)); ctx.lineTo(GX1, Y(gy)); ctx.stroke();
  }

  ctx.strokeStyle = "#365a72";
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(GX0, Y(0)); ctx.lineTo(GX1, Y(0)); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(X(0), GY1); ctx.lineTo(X(0), GY0); ctx.stroke();

  ctx.fillStyle = "#365a72";
  ctx.font = "15px sans-serif";
  for (let gx = -4; gx <= 4; gx++) {
    if (gx === 0) continue;
    ctx.beginPath(); ctx.moveTo(X(gx), Y(0) - 4); ctx.lineTo(X(gx), Y(0) + 4); ctx.stroke();
    ctx.fillText(String(gx), X(gx) - 9, Y(0) + 21);
  }
  for (let gy = 2; gy <= 16; gy += 4) {
    ctx.beginPath(); ctx.moveTo(X(0) - 4, Y(gy)); ctx.lineTo(X(0) + 4, Y(gy)); ctx.stroke();
    ctx.fillText(String(gy), X(0) + 8, Y(gy) + 5);
  }
  ctx.fillText("O", X(0) - 16, Y(0) + 20);
  ctx.font = "bold 16px sans-serif";
  ctx.fillText("x", GX1 - 14, Y(0) - 10);
  ctx.fillText("y", X(0) + 10, GY0 + 15);

  // ---------- 绘图辅助（一律裁剪，不压缩 y 值） ----------
  function clipPlot() {
    ctx.beginPath();
    ctx.rect(GX0, GY0, GX1 - GX0, GY1 - GY0);
    ctx.clip();
  }
  function plotSeg(xa, ya, xb, yb, color, width, dash) {
    ctx.save(); clipPlot();
    ctx.strokeStyle = color;
    ctx.lineWidth = width || 2;
    ctx.setLineDash(dash || []);
    ctx.beginPath();
    ctx.moveTo(X(xa), Y(ya));
    ctx.lineTo(X(xb), Y(yb));
    ctx.stroke();
    ctx.restore();
  }
  function plotDot(x, y, color, r) {
    ctx.save(); clipPlot();
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(X(x), Y(y), r || 6, 0, TAU); ctx.fill();
    ctx.restore();
  }
  function plotLabel(x, y, text, color, dx, dy) {
    const px = clamp(X(x) + (dx || 0), GX0 + 6, GX1 - 70);
    const py = clamp(Y(y) + (dy || 0), GY0 + 22, GY1 - 8);
    ctx.fillStyle = color;
    ctx.font = "bold 17px sans-serif";
    ctx.fillText(text, px, py);
  }

  // ---------- 曲线 ----------
  ctx.save(); clipPlot();
  ctx.strokeStyle = "#236fb5";
  ctx.lineWidth = 3.5;
  ctx.lineJoin = "round";
  ctx.beginPath();
  const NP = 400;
  for (let i = 0; i <= NP; i++) {
    const xx = xmin + (xmax - xmin) * i / NP;
    const yy = f(xx);
    const px = X(xx), py = Y(yy);
    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
  }
  ctx.stroke();
  ctx.restore();

  // ---------- 切线（只有导数存在时才画） ----------
  if (si >= 2 && Number.isFinite(deriv)) {
    plotSeg(xmin, fp + deriv * (xmin - x0), xmax, fp + deriv * (xmax - x0), "#9b55b6", 2, [9, 6]);
  }

  // ---------- 割线 ----------
  if (si === 3) {
    // S4：同一 x0 下并排画左侧 h=−|h| 与右侧 h=+|h| 的割线
    plotSeg(x0, fp, x0 - mag, f(x0 - mag), "#c0392b", 2.5);
    plotSeg(x0, fp, x0 + mag, f(x0 + mag), "#1e8e6a", 2.5);
  } else if (si === 5) {
    // S6：|x| 在原点，左右两条单侧割线，不合成切线
    plotSeg(x0, fp, x0 - mag, f(x0 - mag), "#c0392b", 3);
    plotSeg(x0, fp, x0 + mag, f(x0 + mag), "#1e8e6a", 3);
  } else {
    const qxx = x0 + h, qyy = f(qxx);
    plotSeg(x0, fp, qxx, fp, "#e58b32", 2, [6, 5]);
    plotSeg(qxx, fp, qxx, qyy, "#e58b32", 2, [6, 5]);
    plotSeg(x0, fp, qxx, qyy, "#7a4aa8", 3);
  }

  // ---------- S5 误差竖条 ----------
  if (si === 4 && Number.isFinite(deriv)) {
    const qxx = x0 + h;
    plotSeg(qxx, fp + deriv * h, qxx, f(qxx), "#d84b4b", 4);
  }

  // ---------- 点与标注 ----------
  plotDot(x0, fp, "#f28e2b", 7);
  plotLabel(x0, fp, "P", "#a3591a", 10, -10);

  if (si === 3 || si === 5) {
    plotDot(x0 - mag, f(x0 - mag), "#c0392b", 6);
    plotDot(x0 + mag, f(x0 + mag), "#1e8e6a", 6);
    plotLabel(x0 - mag, f(x0 - mag), "Q−", "#a02c20", -34, -10);
    plotLabel(x0 + mag, f(x0 + mag), "Q+", "#14614a", 10, -10);
  } else {
    const qxx = x0 + h, qyy = f(qxx);
    plotDot(qxx, qyy, "#7a4aa8", 6);
    plotLabel(qxx, qyy, "Q", "#5c3480", 10, -10);
  }

  // ---------- 图例 ----------
  ctx.font = "16px sans-serif";
  ctx.fillStyle = "#236fb5"; ctx.fillText("▬ 蓝：曲线", 45, 86);
  ctx.fillStyle = "#e58b32"; ctx.fillText("▬ 橙：增量", 165, 86);
  ctx.fillStyle = "#7a4aa8"; ctx.fillText("▬ 紫：割线/切线", 285, 86);

  // ---------- 数值面板 ----------
  const BX = 636, BY = 90, BW = 286, BH = 330;
  ctx.fillStyle = "#eef5fa";
  ctx.fillRect(BX, BY, BW, BH);
  ctx.strokeStyle = "#c6d9e5";
  ctx.lineWidth = 1;
  ctx.strokeRect(BX + 0.5, BY + 0.5, BW - 1, BH - 1);

  const titles = [
    "固定点与附近的动点",
    "用增量构造割线斜率",
    "从右侧逼近切线",
    "左右极限必须一致",
    "切线为何能近似曲线",
    "连续的尖点为何不可导"
  ];
  ctx.fillStyle = "#18324a";
  ctx.font = "bold 18px sans-serif";
  ctx.fillText("S" + (si + 1) + " " + titles[si], BX + 14, BY + 32);

  ctx.strokeStyle = "#c6d9e5";
  ctx.beginPath(); ctx.moveTo(BX + 12, BY + 46); ctx.lineTo(BX + BW - 12, BY + 46); ctx.stroke();

  let rows, formulas;
  if (isAbs) {
    rows = [
      "x₀ = 0（尖点，锁定）",
      "|h| = " + fmt(mag, 2) + "，h = ± |h|",
      "右差商 = +1.00",
      "左差商 = −1.00",
      "左右极限不相等",
      "f 在 0 连续但不可导"
    ];
    formulas = [
      "m(h) = |h| / h",
      "h > 0 → 1，h < 0 → −1",
      "f′(0) 不存在"
    ];
  } else {
    rows = [
      "x₀ = " + fmt(x0, 2),
      "h = " + (h >= 0 ? "+" : "−") + fmt(Math.abs(h), 3),
      "m(h) = " + fmt(slope, 4),
      "2x₀ + h = " + fmt(2 * x0 + h, 4),
      "f′(x₀) = 2x₀ = " + fmt(deriv, 3),
      "h² 误差 = " + fmt(Math.abs(residual), 6)
    ];
    if (si >= 4) {
      formulas = [
        "L(x) = x₀² + 2x₀(x − x₀)",
        "误差 h²，h²/|h| = |h| → 0",
        "f′(x₀) = lim m(h) = 2x₀"
      ];
    } else {
      formulas = [
        "m = [f(x₀+h) − f(x₀)] / h",
        "= [(x₀+h)² − x₀²] / h",
        "= 2x₀ + h    (h ≠ 0)"
      ];
    }
  }

  ctx.font = "17px sans-serif";
  ctx.fillStyle = "#2f4a5e";
  for (let i = 0; i < rows.length; i++) {
    ctx.fillText(rows[i], BX + 14, BY + 76 + i * 28);
  }

  ctx.strokeStyle = "#c6d9e5";
  ctx.beginPath(); ctx.moveTo(BX + 12, BY + 236); ctx.lineTo(BX + BW - 12, BY + 236); ctx.stroke();

  ctx.fillStyle = "#7a4aa8";
  ctx.font = "17px sans-serif";
  for (let i = 0; i < formulas.length; i++) {
    ctx.fillText(formulas[i], BX + 14, BY + 262 + i * 28);
  }

  return { metrics: {
    scene: si + 1,
    elapsedSeconds: Number(sec.toFixed(3)),
    x0: Number(x0.toFixed(4)),
    h: Number(h.toFixed(5)),
    slope: Number.isFinite(slope) ? Number(slope.toFixed(5)) : "不存在",
    derivative: Number.isFinite(deriv) ? Number(deriv.toFixed(4)) : "不存在",
    residual: Number.isFinite(residual) ? Number(residual.toFixed(6)) : "不适用",
    example: isAbs ? "|x|" : "x^2"
  }};
}
